/**
 * Reviewed scenario families for the reasoning trainer. These are real different
 * decision situations, not guesses generated by a language model at runtime.
 * Player-seat permutations are applied by mafiaReasoningCourse.ts after selection.
 */
import type { ReasoningCase, ReasoningDecision } from './mafiaReasoningCourse.ts';

const single = (prompt: string, choices: Array<[string, 0 | 1 | 2, string]>): ReasoningDecision => ({
  prompt, options: choices.map(([label, points, feedback]) => ({ label, points, feedback })),
});
const multi = (prompt: string, choices: Array<[string, boolean, string]>): ReasoningDecision => ({
  prompt, mode: 'multiple',
  options: choices.map(([label, plausible, feedback]) => ({ label, points: plausible ? 2 : 0, plausible, feedback })),
});

